PROG_TRAIN = [('Implement JWT authentication in Node.js.', 'Use jsonwebtoken library. Sign token with secret and expiry. Verify on protected routes. Store in httpOnly cookie or Authorization header.'), ('How to prevent SQL injection in PHP.', 'Always use prepared statements with PDO. Never interpolate user input into SQL. Use bindParam or bindValue with typed parameters.'), ('Implement CSRF protection in a web app.', 'Generate random token per session. Include in forms as hidden field. Verify on POST requests. Use SameSite cookie attribute.'), ('Build a REST API with proper error handling.', 'Use consistent JSON error format. Return appropriate HTTP status codes. Log errors server-side. Validate input. Handle not-found, unauthorized, validation errors.'), ('How to implement rate limiting in PHP.', 'Use Redis to store request counts per IP/API key. Sliding window algorithm. Return 429 with Retry-After header. Different limits per endpoint.'), ('Implement file upload validation in PHP.', 'Check $_FILES errors, file size, MIME type with finfo, extension against whitelist. Generate random filename. Store outside web root.'), ('Build a WebSocket chat server.', 'Use ws library in Node.js. Handle connection, message, disconnect events. Broadcast to room members. Store message history. Handle reconnection.'), ('How to implement pagination in PHP/MySQL.', 'Use LIMIT/OFFSET with prepared statements. Calculate total count separately. Return metadata: page, per_page, total, has_next.'), ('Implement a secure login system.', 'Hash password with password_verify. Rate limit login attempts. Use httpOnly cookies. Implement session fixation protection. Add account lockout.'), ('Build a JSON API with PHP.', 'Set Content-Type header. Validate JSON input. Use http_response_code for errors. Return consistent response format. Handle CORS.'), ('How to implement soft deletes.', 'Add deleted_at timestamp column. Filter queries by deleted_at IS NULL. Restore by setting deleted_at to NULL. Cascade to related records.'), ('Implement image processing in PHP.', 'Use GD library or Imagick. Resize, crop, compress. Validate image dimensions and type. Generate thumbnails. Store in private directory.'), ('Build a real-time notification system.', 'Event-driven architecture. WebSocket for push. Store in database for persistence. Batch notifications. Support multiple channels.'), ('How to implement optimistic locking.', 'Add version column to database. Include version in UPDATE WHERE clause. If affected rows is 0, someone else updated first. Retry or inform user.'), ('Implement a search feature with MySQL.', 'Use FULLTEXT index for text search. LIKE for simple patterns. Consider Elasticsearch for complex search. Add filters and sorting.'), ('Build a file sharing system.', 'Generate unique file ID. Store file metadata in DB. Support access control (owner, shared users). Generate time-limited download links.'), ('How to handle concurrent API requests.', 'Use idempotency keys for POST requests. Deduplicate by key. Return cached response for duplicate requests. Implement request deduplication.'), ('Implement a webhook receiver.', 'Verify signature with HMAC. Validate payload schema. Process asynchronously via queue. Return 200 quickly. Retry on failure.'), ('Build a role-based access control system.', 'Define roles and permissions. Assign roles to users. Check permissions at middleware level. Cache permission checks.'), ('How to implement a caching strategy.', 'Cache-aside with Redis. Cache database query results. Set appropriate TTL. Invalidate on data change. Handle cache stampede.'), ('Implement a background job processor.', 'Use Redis queue with worker processes. Support retries with exponential backoff. Dead letter queue for failed jobs. Monitor queue depth.'), ('Build a logging and monitoring system.', 'Structured JSON logging. Different log levels. Centralized log aggregation. Alert on error patterns. Performance metrics.'), ('How to implement database migrations.', 'Version-controlled SQL files. Track applied migrations. Support up/down operations. Test on copy of production data.'), ('Implement a payment integration.', 'Use Stripe/PayPal SDK. Idempotent requests. Webhook for async events. Handle failures gracefully. PCI compliance considerations.'), ('Build a dashboard with real-time data.', 'WebSocket or Server-Sent Events for updates. Aggregate metrics server-side. Cache expensive queries. Update charts incrementally.'), ('How to optimize slow database queries.', 'Use EXPLAIN to analyze query plan. Add appropriate indexes. Avoid SELECT *. Optimize JOINs. Consider query rewriting.'), ('Implement error tracking and alerting.', 'Global error handler. Send errors to tracking service (Sentry). Alert on error rate spikes. Stack traces and context.'), ('Build a multi-language support system.', 'Use i18n library. Extract strings to resource files. Support pluralization. Date/number formatting by locale. RTL support.'), ('How to implement data validation.', 'Server-side validation for all inputs. Client-side for UX. Whitelist approach. Validate types, lengths, ranges. Return specific error messages.'), ('Build a notification preference system.', 'Store per-user, per-notification-type preferences. Support channels: email, push, in-app. Respect do-not-disturb windows.')]

